2px;display:flex;justify-content:space-between;gap:6px}.metric-icon{width:27px;height:27px;display:grid;place-items:center;background:#edf3ff;color:var(--blue);border-radius:8px}.metric-value{font-size:29px;font-weight:700;line-height:1.4;margin:12px 0 7px;direction:ltr;text-align:right;overflow-wrap:anywhere}.metric small{font-size:10px;color:var(--muted)}.metric:first-child{background:var(--blue);color:white;border:0}.metric:first-child .metric-label,.metric:first-child small{color:#dbe5ff}.metric:first-child .metric-icon{background:#ffffff24;color:white}.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:22px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:24px}.section-head p{font-size:11px;margin-top:6px}.section-head label{font-size:11px}.pill{padding:4px 10px;background:#f0f4fa;border-radius:7px;color:var(--muted);font-size:10px;white-space:nowrap}.sales-chart{height:230px;direction:ltr}.sales-chart svg{width:100%;height:195px;overflow:visible}.chart-labels{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-top:12px}.comparison{margin-top:20px;border-top:1px solid var(--line);padding-top:14px;font-size:12px;color:var(--muted)}.status-list{display:grid;gap:17px}.status-row>div{display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px}.bar{height:6px;background:#edf1f7;border-radius:20px;overflow:hidden}.bar i{height:100%;display:block;background:var(--blue);border-radius:20px}.status-row:nth-child(2n) .bar i{background:#28ab94}.status-row:nth-child(3n) .bar i{background:#f3b75e}.note{font-size:10px;color:var(--muted);background:#f7f9fc;border-radius:9px;padding:12px;margin-top:24px}.table-scroll{max-width:100%;overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:right;white-space:nowrap;font-size:12px}th{background:#f8fafd;color:#8190a4;font-weight:400;font-size:11px;padding:13px 14px;border-bottom:1px solid var(--line)}td{padding:17px 14px;border-bottom:1px solid #f0f3f7}tr:last-child td{border:0}td button{background:none;border:0;color:var(--blue);font-weight:700;text-align:right}.shop-cell{display:flex;align-items:center;gap:10px}.shop-avatar{width:33px;height:33px;background:#eff3fb;color:#4672a9;border-radius:10px;display:grid;place-items:center}.shop-cell small{display:block;font-size:10px;color:var(--muted);font-weight:400}.rank-list{display:grid;gap:18px}.rank-item{display:flex;align-items:center;gap:12px;font-size:12px}.rank-number{width:30px;height:30px;background:#f2f5fb;color:var(--muted);border-radius:8px;display:grid;place-items:center}.rank-name{flex:1;min-width:0;overflow-wrap:anywhere}.rank-name small{display:block;color:var(--muted);font-size:10px}.rank-item>b{color:var(--blue);white-space:nowrap}.detail-stats>div{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.detail-stats>div span{color:var(--muted)}.text-link{color:var(--blue);font-size:12px}.activity-entry{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:12px;padding:18px 0;border-bottom:1px solid var(--line)}.activity-dot{height:30px;width:30px;display:grid;place-items:center;border-radius:50%;background:#eff4ff;color:var(--blue)}.activity-entry h3{font-size:12px;margin:0;overflow-wrap:anywhere}.activity-entry p,.activity-entry time{font-size:10px;color:var(--muted)}.activity-entry button{background:none;border:0;color:var(--blue);padding:0;font-size:11px}.activity-entry details{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.activity-entry pre{white-space:pre-wrap;direction:ltr;text-align:left;max-width:100%;font-size:11px}.activity-list{margin-bottom:15px}.empty{padding:35px 10px;color:var(--muted);text-align:center;font-size:12px}.notice{padding:14px 18px;border-radius:10px;margin:15px 0;font-size:12px}.error{background:#fff2ef;color:#a13428;border:1px solid #f5d9d2}.data-notes{padding:10px 4px 60px;font-size:11px;color:var(--muted)}.data-notes p{margin-top:8px}.order-dialog{color:var(--ink);background:white;border:1px solid var(--line);border-radius:18px;width:min(620px,calc(100% - 24px));max-height:calc(100dvh - 32px);padding:24px;overflow:auto}.order-dialog::backdrop{background:#12253c88}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.dialog-head button{border:0;background:#f2f5f9;border-radius:50%;width:40px;height:40px;font-size:24px}.order-detail-line{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding:12px 0;font-size:12px;overflow-wrap:anywhere}.order-detail-line span{color:var(--muted);flex-shrink:0}.order-detail-line b{text-align:left;min-width:0;overflow-wrap:anywhere}.order-dialog .button{display:inline-block;margin-top:20px}
@media(min-width:1550px){.analytics-main{padding-inline:50px}.metrics{gap:22px}}
@media(max-width:1150px){.analytics-sidebar{width:195px;flex-basis:195px;padding:25px 14px}.analytics-main{padding-inline:22px}.overview-grid{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr)}.metric{padding:15px}.metric-value{font-size:24px}}
@media(max-width:900px){.analytics-sidebar{display:none}.analytics-main{padding-inline:20px}.page-intro h1{font-size:25px}}
@media(max-width:650px){body{font-size:13px}.analytics-main{padding-inline:12px}.analytics-top{min-height:58px;flex-wrap:wrap;padding:10px 0;font-size:10px}.page-intro{align-items:start;margin:23px 0 18px;flex-direction:column}.page-intro h1{font-size:24px}.page-intro .button{align-self:end}.filters{padding:14px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.filters .shop-filter{grid-column:1/-1;min-width:0}.filters input,.filters select,.section-head input,.section-head select{font-size:16px;min-width:0}.presets{grid-column:1/-1;justify-content:center}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:16px 0}.metric{padding:14px;min-height:135px}.metric-value{font-size:23px}.metric-label{font-size:11px}.overview-grid{grid-template-columns:minmax(0,1fr);gap:0}.panel{padding:18px 14px;margin-bottom:16px;border-radius:13px}.section-head{align-items:start;flex-wrap:wrap}.section-head h2{font-size:15px}.section-head input{max-width:160px}.activity-entry{grid-template-columns:26px minmax(0,1fr)}.activity-entry time{grid-column:2}.sales-chart{height:210px}.sales-chart svg{height:175px}.order-dialog{padding:18px}.data-notes{padding-bottom:90px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
/* Dark theme, matching the rest of the Ozman dashboard. */
:root{color-scheme:dark;--ink:#eef7fb;--muted:#9eb4c2;--line:#1d3b49;--blue:#16d3ee;--bg:#071118;--green:#55e9a0;--panel:#0c1b24}
body{background:radial-gradient(circle at 85% 0,rgba(0,207,242,.10),transparent 30%),var(--bg);font-family:Cairo,Tahoma,'Segoe UI',Arial,sans-serif}
.analytics-sidebar{background:#081720;border-left-color:var(--line)}.brand-icon{background:linear-gradient(135deg,#16d3ee,#3a7bff);color:#04202a}
.analytics-sidebar nav a:hover,.analytics-sidebar nav a.selected{background:rgba(22,211,238,.12);color:var(--blue)}
.admin-person>span,.shop-avatar,.rank-number,.metric-icon,.activity-dot,.dialog-head button{background:#102b37;color:var(--blue)}
.panel,.metric,.order-dialog{background:linear-gradient(145deg,rgba(15,37,48,.96),rgba(7,19,26,.98));border-color:var(--line);box-shadow:0 16px 40px rgba(0,0,0,.2);color:var(--ink)}
.metric:first-child{background:linear-gradient(135deg,#0fb6d4,#3a62ff);color:#fff}.metric:first-child .metric-label,.metric:first-child small{color:#e3f7ff}
.secondary,.filters input,.filters select,.section-head input,.section-head select{background:#081720;color:var(--ink);border-color:var(--line)}
.primary{background:linear-gradient(135deg,#16d3ee,#3a7bff);border:0;color:#04202a;font-weight:800}
.presets button,.pill{background:#102b37;color:var(--blue)}
th{background:#0a1c25;color:var(--muted)}td{border-bottom-color:#132c38}
.note{background:#081720;color:var(--muted)}.bar{background:#132c38}
.error{background:rgba(160,71,90,.14);color:#ffb1c0;border-color:#7a3446}
.analytics-top b{color:#3d5a68}.live-label{color:var(--green)}
.order-dialog::backdrop{background:rgba(0,0,0,.6)}
/* New insight blocks */
.overview-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}
.mini-title{font-size:13px;margin:20px 0 10px;color:var(--ink)}.mini-title.up{color:var(--green)}.mini-title.down{color:#ff9aae}
.alerts-list{display:grid;gap:10px}.alert-item{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;border:1px solid var(--line);background:#081720}
.alert-item.clickable,.activity-entry.clickable{cursor:pointer;transition:border-color .15s,background .15s}.alert-item.clickable:hover,.alert-item.clickable:focus-visible{border-color:var(--blue);outline:none}.activity-entry.clickable:hover{background:rgba(22,211,238,.06)}
.alert-item p{flex:1;margin:0;color:var(--ink);font-size:13px}.alert-item button{border:1px solid var(--line);background:#102b37;color:var(--blue);border-radius:10px;padding:6px 12px;font-size:12px;white-space:nowrap}
.alert-icon{font-size:20px}.alert-danger{border-color:#7a3446;background:rgba(160,71,90,.14)}.alert-warn{border-color:#6a5420;background:rgba(255,209,102,.07)}
.funnel{display:grid;gap:10px;margin-bottom:16px}.funnel-step{position:relative;display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:12px;background:#081720;overflow:hidden}
.funnel-step i{position:absolute;inset-block:0;inset-inline-start:0;background:linear-gradient(90deg,rgba(22,211,238,.28),rgba(58,123,255,.18));z-index:0}.funnel-step>*:not(i){position:relative;z-index:1}
.funnel-step span{color:var(--muted);min-width:70px}.funnel-step b{font-size:20px}.funnel-step small{margin-inline-start:auto;color:var(--blue);font-weight:800}
.row-warn td{color:#ffd166}
.heatmap{display:grid;grid-template-columns:62px repeat(24,minmax(0,1fr));gap:3px;direction:ltr;font-size:10px;color:var(--muted)}
.hm-day{direction:rtl;text-align:right;padding-inline-end:6px;line-height:20px}.hm-hour{text-align:center}.hm-cell{height:20px;border-radius:4px;background:rgba(22,211,238,var(--a,.05))}.hm-cell.zero{background:#0b1f29}
@media(max-width:1150px){.overview-grid.three{grid-template-columns:minmax(0,1fr)}}
@media(max-width:650px){.heatmap{grid-template-columns:44px repeat(24,minmax(0,1fr));gap:2px;font-size:9px}.hm-cell{height:16px}.alert-item{flex-wrap:wrap}.funnel-step b{font-size:17px}}

/* Analysis assistant */
.assistant-panel{border-color:rgba(22,211,238,.35)!important}.assistant-panel .section-head{align-items:flex-start;gap:12px}
.assistant-chips{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 14px}.assistant-chips button{border:1px solid var(--line);background:#081720;color:var(--ink);border-radius:999px;padding:6px 13px;font-size:12px;cursor:pointer}.assistant-chips button:hover{border-color:var(--blue);color:var(--blue)}
.assistant-log{display:grid;gap:12px;max-height:560px;overflow:auto;padding:4px 2px;overscroll-behavior:contain}.assistant-empty{color:var(--muted);font-size:13px;padding:10px 0}
.assistant-msg{border-radius:14px;padding:12px 15px;font-size:13.5px;line-height:1.9;overflow-wrap:anywhere}.assistant-msg.user{background:#102b37;color:var(--ink);justify-self:start;max-width:85%}.assistant-msg.bot{background:#081720;border:1px solid var(--line)}
.assistant-msg h4{margin:10px 0 4px;color:var(--blue);font-size:14px}.assistant-msg h4:first-child{margin-top:0}.assistant-msg ul,.assistant-msg ol{margin:4px 0;padding-inline-start:20px}.assistant-msg p{margin:4px 0}.assistant-msg b{color:#fff}
.assistant-msg.error{border-color:#7a2b2b;color:#ffb4b4}.assistant-msg.wait{color:var(--muted)}.assistant-msg.wait::after{content:'';display:inline-block;width:1.2em;text-align:start;animation:asDots 1.2s steps(4) infinite}@keyframes asDots{0%{content:''}25%{content:'.'}50%{content:'..'}75%{content:'...'}}
.assistant-form{display:flex;gap:10px;margin-top:14px;align-items:stretch}.assistant-form textarea{flex:1;resize:vertical;min-height:46px;border:1px solid var(--line);background:#081720;color:var(--ink);border-radius:12px;padding:10px 12px;font:inherit}.assistant-form textarea:focus{outline:none;border-color:var(--blue)}
.assistant-tools{display:flex;gap:10px;margin-top:8px}.assistant-tools button{background:none;border:0;color:var(--blue);font-size:12px;cursor:pointer;padding:0}
@media(max-width:650px){.assistant-panel .section-head{flex-direction:column}.assistant-panel .section-head .button{width:100%}.assistant-form{flex-direction:column}.assistant-msg.user{max-width:100%}}
</style>
